var t=[{title:`Waarom je beide combineert`,text:`Krachttraining verbetert kracht en spierfunctie, en aerobe activiteit ondersteunt uithoudingsvermogen en de gezondheid van hart en longen. Richtlijnen voor de volksgezondheid raden beide aan. Slechts één doen kan delen van je fitheid achterlaten, vooral als je dagelijkse doelen kracht, loopvermogen en lang actief blijven omvatten.`},{title:`Het interferentie-effect`,text:`Zeer grote hoeveelheden duurwerk kunnen soms de winst in explosief vermogen of sommige krachtuitkomsten verminderen, vergeleken met alleen krachttraining. Recente overzichten vinden echter dat gecombineerde training over het algemeen aerobe capaciteit en kracht samen verbetert, en de meeste recreatieve trainers verliezen er geen echte spiergroei door.`},{title:`Kies een praktische volgorde`,text:`Is kracht je prioriteit, doe dan de veeleisende lifts terwijl je fris bent en de rustige cardio erna. Is conditie je hoofddoel, doe dan eerst het belangrijke duurwerk. Zware trainingen enkele uren uit elkaar of op verschillende dagen plannen kan helpen tegen vermoeidheid, vooral bij gevorderde training.`},{title:`Breng zware en rustige dagen in balans`,text:`Doe bijvoorbeeld twee full-body-krachtdagen plus twee of drie stevige wandelingen en een optionele matige fietstraining. Een ervaren atleet moet zware looptrainingen en krachtsessies voor de benen misschien zorgvuldig timen. Lijden je prestaties en herstel eronder, stop dan met het stapelen van intervallen op volle kracht bovenop elke beentraining.`},{title:`TrainUp gebruiken`,text:`Je doel in Profiel (algemene fitheid, kracht of conditie) geeft aan welk soort werk je eerst doet terwijl je beide blijft trainen. Cardio verpest je krachtvooruitgang niet automatisch. Houd de herhalingen die je mist en je gemiddelde inspanning in Geschiedenis in de gaten. Als je je schema opnieuw maakt, wordt het lichter als 2 van je laatste 3 trainingen zeer zwaar waren (RPE 9 of hoger) of voor minder dan 60% zijn afgerond.`}];var i=[{label:`Paraplureview 2026: kracht- en duurtraining gecombineerd`,url:`https://pubmed.ncbi.nlm.nih.gov/41762427/`},{label:`Beweegaanbevelingen van de CDC voor volwassenen`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};